export function getTodayDevotional(viewedIds: string[] = []): Devotional {
  const today = new Date();
  const dayOfYear = Math.floor((today.getTime() - new Date(today.getFullYear(), 0, 0).getTime()) / 86400000);
  
  const unviewed = devotionals.filter(d => !viewedIds.includes(d.id));
  
  if (unviewed.length > 0) {
    return unviewed[dayOfYear % unviewed.length];
  }
  
  return devotionals[dayOfYear % devotionals.length];
}

export function getPersonalizedDevotional(viewedIds: string[], preferences: string[] = []): Devotional {
  const unviewed = devotionals.filter(d => !viewedIds.includes(d.id));
  
  if (unviewed.length === 0) {
    return devotionals[Math.floor(Math.random() * devotionals.length)];
  }
  
  if (preferences.length > 0) {
    const preferredDevotionals = unviewed.filter(d => 
      preferences.some(pref => 
        d.title.toLowerCase().includes(pref.toLowerCase()) ||
        d.reflection.toLowerCase().includes(pref.toLowerCase())
      )
    );
    
    if (preferredDevotionals.length > 0) {
      return preferredDevotionals[Math.floor(Math.random() * preferredDevotionals.length)];
    }
  }
  
  return unviewed[Math.floor(Math.random() * unviewed.length)];
}

// Get theme keywords from devotional to match with prayer and study
export function getCorrelatedDevotionalTheme(devotional: Devotional): string[] {
  const keywords: string[] = [];
  const text = `${devotional.title} ${devotional.reflection}`.toLowerCase();
  
  // Common spiritual themes with more specific matching to avoid false positives
  const themeMap: Record<string, string[]> = {
    'finances': ['money', 'wealth', 'financial', 'steward', 'provision', 'tithe', 'giving', 'rich', 'poor', 'contentment'],
    'peace': ['peace', 'anxiety', 'worry', 'calm', 'rest', 'tranquil'],
    'strength': ['strength', 'courage', 'power', 'strong', 'mighty', 'endure'],
    'faith': ['faith', 'trust', 'believe', 'hope'],
    'guidance': ['guidance', 'wisdom', 'direction', 'path', 'choose', 'decision'],
    'forgiveness': ['forgive', 'mercy', 'grace', 'pardon', 'redemption'],
    'gratitude': ['thank', 'grateful', 'praise', 'blessing', 'appreciate'],
    'love': ['love others', 'compassion', 'kindness', 'serve others', 'care for others'],
    'health': ['health', 'body', 'physical', 'wellness', 'healing'],
    'parenting': ['parent', 'children', 'child', 'family'],
    'career': ['work', 'career', 'job', 'profession', 'business'],
    'purpose': ['purpose', 'calling', 'mission', 'identity'],
  };
  
  // Check finances first as it's very specific
  for (const [theme, searchTerms] of Object.entries(themeMap)) {
    if (searchTerms.some(term => text.includes(term))) {
      keywords.push(theme);
    }
  }
  
  return keywords.length > 0 ? keywords : ['peace']; // Default to peace if no match
}
